import{t as e}from"./cook-CDgGBDXj.js";import{t}from"./restaurant-CYZ0I4j5.js";var n=[{slug:`moskva`,name:`Москва`,nameIn:`Москве`,nameOf:`Москвы`,region:`Москва и Московская область`,population:`13,1 млн`,intro:`В Москве самая плотная ресторанная сцена в стране: от сетевых кофеен до ресторанов высокой кухни и крупных кейтеринговых операторов. Здесь проще всего найти смену рядом с домом, но и требования к опыту выше.`,scene:`Спрос распределён по всему городу: Патриаршие и Хамовники ищут опытных официантов и барменов, Сити и Замоскворечье — персонал на бизнес-ланчи, а фуд-холлы и кухни доставки набирают поваров-универсалов почти круглый год.`,districts:[`Патриаршие пруды`,`Хамовники`,`Замоскворечье`,`Москва-Сити`,`Чистые пруды`,`Сокол`],demand:`Повара горячего цеха, су-шефы, официанты, бармены, бариста, пиццайоло и кондитеры. Отдельная категория — персонал на банкеты и корпоративные события.`,season:`Пик — сентябрь–декабрь и март–июнь. Летом добавляются веранды и сезонные площадки, в декабре — корпоративы и банкеты.`,rates:`Смена повара или официанта обычно стоит 4 000–7 000 ₽, на банкетах и ночных сменах ставка выше. Выплата чаще день в день.`,faqs:[{q:`Можно ли найти смену в Москве без опыта?`,a:`Да, в кофейнях, кухнях доставки и на банкетах регулярно берут новичков. Начните с позиций заготовщика, раннера или бариста-стажёра: там обучают на месте.`},{q:`Как выбрать смену рядом с домом?`,a:`В анкете укажите район и максимальное время на дорогу. Заведения в Москве публикуют смены по округам, поэтому можно работать в 20–30 минутах от дома и не тратить час на метро.`},{q:`Сколько платят официанту в Москве?`,a:`Ставка зависит от формата: в кофейне — ниже, в ресторане и на банкетах — выше. Чаевые в Москве обычно существенные, их правила уточняйте до смены.`}]},{slug:`sankt-peterburg`,name:`Санкт-Петербург`,nameIn:`Санкт-Петербурге`,nameOf:`Санкт-Петербурга`,region:`Санкт-Петербург и Ленинградская область`,population:`5,6 млн`,intro:`Петербург — второй по объёму рынок общепита: исторический центр, Петроградка и Васильевский остров держат высокий поток гостей круглый год, а летом к ним добавляются веранды и туристический сезон.`,scene:`На Рубинштейна и Невском проспекте плотность баров и ресторанов максимальная, на Петроградской стороне много кофеен и пекарен, а в Сестрорецке и Курортном районе — сезонные загородные проекты.`,districts:[`Рубинштейна`,`Невский проспект`,`Петроградская сторона`,`Васильевский остров`,`Сенной рынок`,`Сестрорецк`],demand:`Бариста, официанты, бармены и повара. В сезон белых ночей заведения усиливаются раннерами и хостес, а на выходные ищут подмену на кухню.`,season:`Май–сентябрь — туристический пик и веранды, декабрь — новогодние программы. Зимой спрос ровнее, но меньше смен на летних площадках.`,rates:`Типичная ставка — 3 500–6 000 ₽ за смену. В центре и на банкетах выше, в спальных районах — ближе к нижней границе.`,faqs:[{q:`Когда в Петербурге больше всего смен?`,a:`С мая по сентябрь: туристы, веранды и белые ночи. Если нужна максимальная загрузка, планируйте подработку на этот период.`},{q:`Реально ли совмещать смены с учёбой?`,a:`Да, в Петербурге много вузов, и заведения рядом с ними (на Васильевском, Петроградке) часто ищут студентов на вечерние и выходные смены.`},{q:`Нужно ли знать английский?`,a:`В туристическом центре это заметный плюс: часть гостей говорит по-английски. В спальных районах и сетевых кофейнях достаточно русского.`}]},{slug:`novosibirsk`,name:`Новосибирск`,nameIn:`Новосибирске`,nameOf:`Новосибирска`,region:`Новосибирская область`,population:`1,63 млн`,intro:`Крупнейший город Сибири: деловой центр, Академгородок и набережная Оби формируют устойчивый спрос на персонал в общепите, а сибирская кухня — отдельное направление, где ценятся повара с опытом работы с локальными продуктами.`,scene:`В центре и на Речном вокзале сосредоточены гастробары и рестораны, в Академгородке — кофейни и научные кампусы с завтраками и бизнес-ланчами, а кухни доставки набирают поваров на вечерние смены.`,districts:[`Центр`,`Академгородок`,`Набережная Оби`,`Речной вокзал`,`Заельцовский район`],demand:`Повара горячего цеха, универсалы, официанты и бариста. В Академгородке постоянно нужны сотрудники на утренние смены в кофейнях.`,season:`Сентябрь–декабрь и февраль–май. Летом добавляются веранды на набережной, зимой — банкеты и корпоративные события.`,rates:`Ставка — 3 000–5 000 ₽ за смену. В центре и на банкетах выше, в кухнях доставки — стабильно, но без чаевых.`,faqs:[{q:`Есть ли смены в Академгородке?`,a:`Да, но их меньше, чем в центре: в основном кофейни, столовые кампусов и завтраки в отелях. Удобно, если вы живёте в Советском районе.`},{q:`Что такое сибирская кухня для повара?`,a:`Работа с местной рыбой, дичью, грибами и ягодами. Опыт в таких проектах ценится, но на линейные смены берут и без него.`},{q:`Как быстро выплачивают деньги?`,a:`Большинство новосибирских заведений платят в день смены или на следующий рабочий день. Условия указаны в заявке до отклика.`}]},{slug:`ekaterinburg`,name:`Екатеринбург`,nameIn:`Екатеринбурге`,nameOf:`Екатеринбурга`,region:`Свердловская область`,population:`1,54 млн`,intro:`Екатеринбург — столица Урала с сильной барной и гастрономической сценой. Плотность гастробаров и кофеен в центре высокая, поэтому подработку здесь реально найти даже на несколько смен в неделю.`,scene:`Основной поток — вокруг Плотинки, Ельцин Центра и улицы Малышева. В новых жилых районах на ВИЗе и Ботаническом открываются кофейни и пиццерии, которым нужны универсальные сотрудники.`,districts:[`Плотинка`,`Ельцин Центр`,`ВИЗ`,`Ботанический`,`Малышева`],demand:`Бармены, бариста, официанты, повара горячего цеха. Гастробары ищут людей с опытом, сети и кофейни готовы обучать новичков.`,season:`Пик — сентябрь–декабрь и март–май. Летом работают веранды и фестивальные площадки, зимой — банкеты и новогодние корпоративы.`,rates:`Ставка — 3 000–5 000 ₽. Бармены и повара в центре получают ближе к верхней границе, стажёры — по договорённости.`,faqs:[{q:`Можно ли работать в Екатеринбурге только по вечерам?`,a:`Да, гастробары и рестораны центра активно ищут людей на вечерние смены и выходные. Укажите в анкете удобные часы — заведения сами пригласят.`},{q:`Нужен ли опыт для работы барменом?`,a:`В гастробарах обычно да, хотя бы базовый. В кофейнях и пиццериях берут на стажировку с обучением.`},{q:`Много ли смен в новых районах?`,a:`Меньше, чем в центре, но они стабильнее: кофейни и пиццерии в ЖК ищут сотрудников на постоянный график и часто готовы подстроиться под учёбу.`}]},{slug:`kazan`,name:`Казань`,nameIn:`Казани`,nameOf:`Казани`,region:`Республика Татарстан`,population:`1,31 млн`,intro:`Казань сочетает туристический центр и крупные сети: на Баумана и вокруг Кремля высокий поток гостей, а в новых районах открываются кофейни и семейные рестораны. Татарская кухня — сильный локальный бренд, который любят и туристы, и горожане.`,scene:`Вахитовский район и Профсоюзная улица — концентрация ресторанов и баров. В Горках и ЖК «Салават Купере» спрос формируют семейные форматы и кофейни у дома.`,districts:[`Кремль`,`Улица Баумана`,`Профсоюзная`,`Вахитовский район`,`Горки`,`Салават Купере`],demand:`Официанты, повара, бариста и кондитеры. В туристический сезон нужны сотрудники со знанием меню и готовностью работать с большим потоком гостей.`,season:`Май–сентябрь — туристы и веранды, декабрь–январь — новогодние программы. Осенью и весной спрос на смены стабильный за счёт деловых завтраков.`,rates:`Ставка — 3 000–5 000 ₽ за смену. В центре и в туристический сезон выше, в семейных ресторанах — средняя по городу.`,faqs:[{q:`Нужно ли знать татарскую кухню?`,a:`Не обязательно, но плюс: часть заведений специализируется на ней, и знание блюд ускоряет выход на смену. Остальному обучают на месте.`},{q:`Когда в Казани больше всего работы?`,a:`В туристический сезон с мая по сентябрь и в новогодние праздники. В это время заведения усиливаются официантами и поварами.`},{q:`Можно ли найти смену в новом районе?`,a:`Да, в Горках и Салават Купере открываются кофейни и рестораны у дома — там меньше конкурс и часто берут без опыта.`}]},{slug:`nizhniy-novgorod`,name:`Нижний Новгород`,nameIn:`Нижнем Новгороде`,nameOf:`Нижнего Новгорода`,region:`Нижегородская область`,population:`1,21 млн`,intro:`После обновления центра и набережных Нижний Новгород стал заметной гастрономической точкой: Рождественская и Верхневолжская набережная собирают бары и рестораны, а туристический поток растёт каждый сезон.`,scene:`Рождественская улица — барный кластер, набережная Федоровского и Верхневолжская — рестораны с видом. В Автозаводском и Советском районах спрос создают сети и кухни доставки.`,districts:[`Рождественская`,`Верхневолжская набережная`,`Нижегородский район`,`Автозавод`,`Советский район`],demand:`Официанты, бармены, повара и бариста. В сезон дополнительно ищут хостес и раннеров на веранды и набережные.`,season:`Май–сентябрь — туристы и набережные, декабрь — новогодние ярмарки. Осенью спрос смещается к банкетам и деловым обедам.`,rates:`Ставка — 3 000–5 000 ₽. На набережных и в центре выше, в спальных районах — ближе к нижней границе.`,faqs:[{q:`Где в Нижнем Новгороде больше смен?`,a:`На Рождественской и в районе набережных: там сосредоточены бары, рестораны и туристический поток. В спальных районах смен меньше, но они стабильнее.`},{q:`Берут ли на работу без опыта?`,a:`В сетевых кофейнях, пиццериях и кухнях доставки — да. В барах центра чаще нужен опыт или уверенная база по напиткам.`},{q:`Что с работой зимой?`,a:`Зимой меньше веранд, но больше банкетов и корпоративов. Смены есть, просто формат другой: залы, выездные события, новогодние программы.`}]},{slug:`chelyabinsk`,name:`Челябинск`,nameIn:`Челябинске`,nameOf:`Челябинска`,region:`Челябинская область`,population:`1,18 млн`,intro:`Челябинск — промышленный город с большим числом сетевых заведений и кухонь доставки. Здесь ценятся пунктуальность и скорость, а порог входа ниже: многие заведения готовы обучать с нуля.`,scene:`Кировка и Центральный район — основная ресторанная зона. На Северо-Западе и в новых ЖК открываются пиццерии и кофейни, а кухни доставки набирают поваров на вечерние смены.`,districts:[`Кировка`,`Центральный район`,`Северо-Запад`,`Тополиная аллея`,`Калининский район`],demand:`Повара-универсалы, пиццайоло, официанты и бариста. Сети ищут сотрудников на постоянный график, доставка — на вечерние и ночные смены.`,season:`Сентябрь–декабрь и март–май. Летом добавляются веранды, зимой — банкеты и доставка, которая растёт в праздники.`,rates:`Ставка — 2 800–4 500 ₽ за смену. В центре и на банкетах выше, в доставке — стабильно с надбавкой за ночь.`,faqs:[{q:`Можно ли устроиться без опыта в Челябинске?`,a:`Да, в сетях и кухнях доставки регулярно набирают новичков. Начните с позиции заготовщика, пиццайоло-стажёра или раннера.`},{q:`Есть ли ночные смены?`,a:`Да, кухни доставки и некоторые бары работают ночью. Ночные смены обычно оплачиваются выше, но требуют готовности к такому графику.`},{q:`Как оплачивается работа в доставке?`,a:`Ставка фиксируется в заявке, выплата обычно день в день. Чаевых меньше, чем в зале, зато нет зависимости от потока гостей.`}]},{slug:`krasnoyarsk`,name:`Красноярск`,nameIn:`Красноярске`,nameOf:`Красноярска`,region:`Красноярский край`,population:`1,19 млн`,intro:`Красноярск — центр Сибири с активной кофейной культурой и сильной локальной кухней. Город компактный: из большинства районов до центра можно добраться за 20–30 минут, поэтому смены в центре доступны почти всем.`,scene:`Центр и набережная Енисея — рестораны и кофейни, Взлётка — новые ЖК с кофейнями у дома, а турбазы на Столбах и за городом ищут поваров на выходные в сезон.`,districts:[`Центр`,`Набережная Енисея`,`Взлётка`,`Столбы`,`Октябрьский район`],demand:`Бариста, повара, официанты и кондитеры. Кофейни — самый стабильный канал подработки, рестораны — выше ставки и требования к опыту.`,season:`Сентябрь–декабрь и май–сентябрь. Летом добавляются веранды и загородные площадки, зимой — банкеты и горнолыжные турбазы.`,rates:`Ставка — 3 000–5 000 ₽. На загородных площадках и в сезон выше, в кофейнях у дома — средняя по городу.`,faqs:[{q:`Много ли работы в кофейнях?`,a:`Да, Красноярск известен кофейной культурой: кофейни есть в центре, в ЖК и в вузах. Туда чаще берут без опыта и обучают.`},{q:`Есть ли смены за городом?`,a:`Да, турбазы и загородные рестораны ищут поваров и официантов на выходные. Обычно предлагают питание и трансфер.`},{q:`Как совмещать смены с основной работой?`,a:`Берите только выходные или вечерние смены: сервис не требует обязательного количества часов в месяц.`}]},{slug:`samara`,name:`Самара`,nameIn:`Самаре`,nameOf:`Самары`,region:`Самарская область`,population:`1,16 млн`,intro:`Самара — город с длинной набережной и сильным сезонным спросом: летом веранды работают на полную, а в центре открываются гастробары и кофейни. Для подработки это удобный рынок: смен много, конкуренция ниже, чем в столицах.`,scene:`Ленинградская и Самарская площадь — ресторанный центр, набережная Волги — сезонные веранды. В Октябрьском и Промышленном районах спрос создают сети и доставка.`,districts:[`Ленинградская`,`Набережная Волги`,`Самарская площадь`,`Октябрьский район`,`Промышленный район`],demand:`Официанты, повара, бариста и бармены. С мая по сентябрь заведения усиливаются на веранды и набережную.`,season:`Май–сентябрь — веранды и туристы, декабрь — корпоративы. В межсезонье спрос ровнее и меньше смен на открытых площадках.`,rates:`Ставка — 2 800–4 500 ₽. На набережной и в центре выше, в сетях — средняя по городу.`,faqs:[{q:`Когда в Самаре больше всего смен?`,a:`С мая по сентябрь, когда открываются веранды и растёт поток гостей. В это время заведения активно ищут официантов и поваров.`},{q:`Можно ли работать только летом?`,a:`Да, сезонная подработка на верандах — обычная практика. Многие заведения берут на 2–4 месяца с возможностью остаться.`},{q:`Берут ли студентов?`,a:`Да, особенно в кофейни и пиццерии рядом с вузами. График можно собрать из вечерних смен и выходных.`}]},{slug:`ufa`,name:`Уфа`,nameIn:`Уфе`,nameOf:`Уфы`,region:`Республика Башкортостан`,population:`1,16 млн`,intro:`Уфа — крупный город с развитой сетью ресторанов и национальной башкирской кухней. Спрос на персонал ровный: сети и банкетные площадки набирают сотрудников круглый год, а кофейни — на утренние смены.`,scene:`Верхнеторговая площадь и центр — рестораны и бары, проспект Октября — сети и кофейни, Черниковка — заведения у дома и кухни доставки.`,districts:[`Верхнеторговая площадь`,`Центр`,`Проспект Октября`,`Черниковка`,`Сипайлово`],demand:`Официанты, повара, бариста и кондитеры. Банкетные площадки ищут персонал на выходные, сети — на постоянный график.`,season:`Сентябрь–декабрь и март–май, плюс летние веранды. Зимой основной объём дают банкеты и корпоративы.`,rates:`Ставка — 2 800–4 500 ₽. На банкетах выше, в кофейнях и сетях — средняя по городу.`,faqs:[{q:`Что нужно знать про башкирскую кухню?`,a:`Для линейных позиций — ничего, обучают на месте. Для повара опыт с национальной кухней будет плюсом при отборе.`},{q:`Есть ли смены на выходные?`,a:`Да, банкеты и свадьбы чаще всего проходят в пятницу–воскресенье, и на них нужны официанты, раннеры и повара.`},{q:`Можно ли работать в Уфе без медкнижки?`,a:`На короткую смену некоторые заведения берут без неё, но для постоянной работы медкнижка почти всегда обязательна.`}]},{slug:`rostov-na-donu`,name:`Ростов-на-Дону`,nameIn:`Ростове-на-Дону`,nameOf:`Ростова-на-Дону`,region:`Ростовская область`,population:`1,14 млн`,intro:`Ростов — южная столица с длинным сезоном веранд и сильной ресторанной сценой на Большой Садовой. Тёплый климат растягивает высокий сезон с апреля по октябрь, поэтому летом смен здесь больше, чем в большинстве городов.`,scene:`Большая Садовая и набережная Дона — рестораны, бары и веранды. В районе Ростов-Арены и новых ЖК открываются сети и кофейни, ориентированные на семьи.`,districts:[`Большая Садовая`,`Набережная Дона`,`Ростов-Арена`,`ЖК Донской`,`Западный`],demand:`Официанты, повара, бармены и бариста. В сезон веранд нужны раннеры и хостес, на банкетах — повара и официанты с опытом.`,season:`Апрель–октябрь — веранды и туристы, декабрь — корпоративы. Зимой спрос ниже, но сети и доставка работают стабильно.`,rates:`Ставка — 3 000–5 000 ₽. На набережной и в сезон выше, в спальных районах — ближе к нижней границе.`,faqs:[{q:`Сколько длится сезон веранд в Ростове?`,a:`С апреля по октябрь, иногда до начала ноября. Это лучшее время для подработки официантом или барменом.`},{q:`Что делать зимой?`,a:`Зимой больше смен в сетях, кофейнях и доставке, а также на корпоративах. Можно перейти в зал или на кухню с постоянным графиком.`},{q:`Нужен ли опыт для работы на веранде?`,a:`Часто нет: сезонные площадки набирают людей под поток гостей и обучают на месте. Опыт ускоряет выход, но не обязателен.`}]},{slug:`krasnodar`,name:`Краснодар`,nameIn:`Краснодаре`,nameOf:`Краснодара`,region:`Краснодарский край`,population:`1,1 млн`,intro:`Краснодар растёт быстрее многих городов России: новые ЖК, парки и гастрокварталы открывают десятки заведений каждый год. Спрос на персонал высокий, а курортный поток делает лето самым прибыльным сезоном.`,scene:`Красная улица и центр — рестораны и кофейни, парк Галицкого — гастроквартал с постоянным потоком гостей. В новых ЖК на Дальнем и в Панораме открываются заведения у дома.`,districts:[`Красная улица`,`Парк Галицкого`,`ЖК Панорама`,`Дальний`,`Центральный округ`],demand:`Бариста, официанты, повара и бармены. Летом добавляются веранды и точки на курортных направлениях, зимой — сети и доставка.`,season:`Май–сентябрь — пик из-за жары, веранд и туристов. Декабрь — корпоративы. В остальное время спрос стабильный за счёт роста города.`,rates:`Ставка — 3 000–5 000 ₽. В парке Галицкого и центре выше, в новых ЖК — средняя по городу.`,faqs:[{q:`Правда ли в Краснодаре много работы в общепите?`,a:`Да, город активно растёт, и новые заведения открываются регулярно. Конкуренция за смены ниже, чем в Москве, а ставки сопоставимы.`},{q:`Можно ли работать на курортах края?`,a:`Да, часть заведений Краснодара имеет проекты в Анапе, Геленджике и Сочи. В сезон туда набирают персонал с проживанием.`},{q:`Что с работой вне сезона?`,a:`Осенью и зимой спрос смещается в сети, кофейни и доставку. Веранды закрываются, но закрытые форматы работают круглый год.`}]},{slug:`omsk`,name:`Омск`,nameIn:`Омске`,nameOf:`Омска`,region:`Омская область`,population:`1,10 млн`,intro:`Омск — город с крепкими сетями и большим числом заведений у дома. Порог входа в общепит ниже, чем в столицах: здесь реально начать с нуля и быстро получить первую смену.`,scene:`Любинский проспект и центр — основная ресторанная зона, набережная Иртыша — сезонные площадки. В Чкаловском и Кировском районах спрос создают сети и доставка.`,districts:[`Любинский проспект`,`Центр`,`Набережная Иртыша`,`Чкаловский`,`Кировский`],demand:`Повара-универсалы, официанты, бариста и пиццайоло. Сети набирают на постоянный график, банкеты — на выходные.`,season:`Сентябрь–декабрь и март–май. Летом открываются веранды, зимой растёт доставка и банкеты.`,rates:`Ставка — 2 600–4 300 ₽. В центре выше, в сетях — средняя по городу.`,faqs:[{q:`Легко ли найти первую работу в общепите в Омске?`,a:`Да, сети и доставка часто берут без опыта. Начните с позиции заготовщика или раннера и постепенно переходите на зал или кухню.`},{q:`Есть ли работа на выходные?`,a:`Да, банкеты и семейные праздники проходят в пятницу–воскресенье, и на них нужны официанты и повара.`},{q:`Как быстро приходят выплаты?`,a:`В большинстве заведений — в день смены или на следующий рабочий день. Условия прописаны в заявке.`}]},{slug:`voronezh`,name:`Воронеж`,nameIn:`Воронеже`,nameOf:`Воронежа`,region:`Воронежская область`,population:`1,05 млн`,intro:`Воронеж — крупный университетский центр, поэтому здесь много молодых сотрудников и гибких графиков. Рестораны и кофейни центра активно ищут людей на вечерние смены и выходные.`,scene:`Проспект Революции и центр — рестораны и бары, набережная Воронежского водохранилища — сезонные веранды, Северный район — сети и кофейни у дома.`,districts:[`Проспект Революции`,`Центр`,`Набережная водохранилища`,`Северный район`,`Коминтерновский`],demand:`Бариста, официанты, повара и бармены. Кофейни рядом с вузами ищут студентов на утренние и вечерние смены.`,season:`Май–сентябрь — веранды и набережная, декабрь — корпоративы. Осенью и весной спрос стабильный за счёт студентов и деловых обедов.`,rates:`Ставка — 2 700–4 500 ₽. В центре и на набережной выше, в сетях — средняя по городу.`,faqs:[{q:`Удобно ли совмещать смены с учёбой?`,a:`Да, в Воронеже много вузов, и заведения рядом с ними подстраиваются под расписание: можно брать утренние, вечерние смены или только выходные.`},{q:`Где больше всего вакансий?`,a:`В центре и на набережной: там сосредоточены рестораны, бары и сезонные веранды. В Северном районе больше сетевых кофеен.`},{q:`Берут ли на работу без опыта?`,a:`Да, кофейни и пиццерии часто обучают с нуля. В рестораны с высокой кухней обычно нужен хотя бы небольшой опыт.`}]},{slug:`perm`,name:`Пермь`,nameIn:`Перми`,nameOf:`Перми`,region:`Пермский край`,population:`1,03 млн`,intro:`Пермь — город с заметной барной и кофейной сценой и сильными локальными проектами. Заведения центра ценят людей, которые готовы учиться, а сети дают стабильный график и понятные выплаты.`,scene:`Комсомольский проспект и центр — бары, рестораны и кофейни, набережная Камы — сезонные площадки, Гайва и новые ЖК — заведения у дома.`,districts:[`Компрос`,`Центр`,`Набережная Камы`,`Гайва`,`Мотовилихинский район`],demand:`Бармены, бариста, официанты и повара. Кофейни и бары — основной канал подработки, рестораны — выше ставки и требования.`,season:`Сентябрь–декабрь и март–май. Летом добавляются веранды и фестивальные площадки, зимой — банкеты.`,rates:`Ставка — 2 700–4 500 ₽. В центре выше, в сетях и доставке — средняя по городу.`,faqs:[{q:`Много ли в Перми работы бариста?`,a:`Да, кофейная culture города развита, и кофейни регулярно ищут сотрудников. Часто берут стажёров с обучением.`},{q:`Есть ли смены в новых районах?`,a:`Да, в Гайве и новых ЖК открываются заведения у дома. Там меньше конкурс и часто более гибкий график.`},{q:`Как получить смену быстрее?`,a:`Заполните анкету полностью, укажите район и готовность к вечерним сменам — заведения приглашают таких кандидатов в первую очередь.`}]},{slug:`volgograd`,name:`Волгоград`,nameIn:`Волгограде`,nameOf:`Волгограда`,region:`Волгоградская область`,population:`1,00 млн`,intro:`Волгоград — город с длинной набережной и развитой сетью заведений. Здесь стабильный спрос на поваров и официантов, а летом добавляются веранды и туристические маршруты.`,scene:`Центральный район и набережная Волги — рестораны и кофейни, Мамаев курган — туристический поток, Красноармейский район — сети и доставка.`,districts:[`Центральный район`,`Набережная Волги`,`Мамаев курган`,`Красноармейский`,`Ворошиловский`],demand:`Повара, официанты, бариста и пиццайоло. Сети и доставка набирают круглый год, банкеты — на выходные.`,season:`Май–сентябрь — набережная и туристы, декабрь — корпоративы. В межсезонье спрос держат сети и доставка.`,rates:`Ставка — 2 600–4 300 ₽. В центре и на набережной выше, в сетях — средняя по городу.`,faqs:[{q:`Есть ли работа летом?`,a:`Да, с мая по сентябрь открываются веранды и растёт туристический поток. Это лучшее время для подработки в зале.`},{q:`Берут ли без опыта?`,a:`Да, сети, пиццерии и доставка обучают с нуля. Начните с заготовщика или раннера.`},{q:`Как быстро можно выйти на смену?`,a:`После заполнения анкеты — в течение нескольких дней. На срочные замены заведения иногда приглашают в тот же день.`}]}],r=[{slug:`tula`,name:`Тула`,nameIn:`Туле`,nameOf:`Тулы`,region:`Тульская область`,population:`около 550 тыс.`,hub:`Москве`,intro:`Тула — город с сильным туристическим потоком: кремль, самовары и пряники привлекают гостей круглый год, а вместе с ними растёт число кафе, кофеен и ресторанов в центре.`,scene:`Основные точки — вокруг кремля, на улице Металлистов и в музее «Тульский пряник». Туристы дают высокий поток в выходные, поэтому заведениям нужны официанты и повара на подмену.`,districts:[`Кремль`,`Улица Металлистов`,`Центр`,`Пролетарский район`,`Заречье`],demand:`Официанты, повара, бариста и кондитеры. В выходные и праздники заведения усиливаются раннерами и хостес.`,season:`Май–сентябрь и новогодние праздники — туристический пик. В остальное время спрос держат сети и кофейни.`,rates:`Ставка — 2 500–4 200 ₽. В центре и в туристический сезон выше, в сетях — средняя по городу.`,faqs:[{q:`Где в Туле больше всего смен?`,a:`В центре, вокруг кремля и на Металлистов: там сосредоточены кафе, рестораны и кофейни с туристическим потоком.`},{q:`Можно ли работать только в выходные?`,a:`Да, туристические выходные — самое загруженное время, и заведения охотно берут людей на подмену в субботу и воскресенье.`},{q:`Берут ли без опыта?`,a:`Да, в кофейнях и сетевых кафе обучают на месте. В рестораны центра чаще нужен хотя бы небольшой опыт.`}]},{slug:`bogoroditsk`,name:`Богородицк`,nameIn:`Богородицке`,nameOf:`Богородицка`,region:`Тульская область`,population:`около 30 тыс.`,hub:`Туле`,intro:`Богородицк — небольшой город с известной усадьбой Бобринских и дворцом-музеем. Туристы приезжают на выходные, поэтому кафе и кофейни у музея и в центре периодически ищут персонал на подмену.`,scene:`Спрос формируют кафе в центре, точки у дворца-музея и придорожные заведения на трассе. В будни поток ниже, в выходные и в сезон экскурсий — заметно выше.`,districts:[`Центр`,`Усадьба Бобринских`,`Трасса М-4`,`Микрорайон`],demand:`Повара-универсалы, официанты и продавцы-бариста. Чаще всего нужны люди на подмену в выходные и на сезон отпусков.`,season:`Май–сентябрь и школьные каникулы. В остальное время смены появляются точечно — удобно совмещать с учёбой.`,rates:`Ставка — 2 000–3 500 ₽ за смену. В придорожных заведениях и на банкетах выше.`,faqs:[{q:`Есть ли в Богородицке работа в общепите?`,a:`Да, но заведений немного: кафе в центре, точки у музея и придорожный общепит. Смены появляются волнами — в выходные и в сезон экскурсий.`},{q:`Что делать, если смен мало?`,a:`Заполните анкету и укажите готовность выезжать в Тулу или Новомосковск: там заведений больше, а дорога занимает около часа.`},{q:`Можно ли начать без опыта?`,a:`Да, в небольших кафе часто берут помощником повара или на кассу с обучением на месте.`}]},{slug:`bolohovo`,name:`Болохово`,nameIn:`Болохове`,nameOf:`Болохово`,region:`Тульская область`,population:`около 9 тыс.`,hub:`Новомосковске и Туле`,intro:`Болохово — небольшой город в Тульской области рядом с Новомосковском. Общепит здесь представлен кафе, столовыми и придорожными точками, а многие жители работают в соседних городах.`,scene:`Смены появляются в местных кафе, столовых на предприятиях и придорожных заведениях. Чаще всего требуются повара-универсалы и продавцы на кассу.`,districts:[`Центр`,`Трасса`,`Рабочие кварталы`],demand:`Повар-универсал, помощник повара, кассир-бариста. График часто сменный, с подменой на выходные.`,season:`Стабильно в течение года, с небольшим ростом летом и в праздники.`,rates:`Ставка — 1 800–3 200 ₽. В Новомосковске и Туле ставки выше на 20–40%.`,faqs:[{q:`Реально ли найти смену в Болохове?`,a:`Да, но выбор небольшой: местные кафе, столовая и придорожный общепит. Заявки появляются не каждый день.`},{q:`Стоит ли смотреть Новомосковск и Тулу?`,a:`Да. Это ближайшие крупные рынки: в Новомосковске заведений заметно больше, дорога занимает 20–30 минут.`},{q:`Какие документы нужны?`,a:`Для работы в общепите обычно нужна медицинская книжка. Без неё иногда берут на короткую подмену, но это стоит уточнять заранее.`}]},{slug:`gryazi`,name:`Грязи`,nameIn:`Грязях`,nameOf:`Грязей`,region:`Липецкая область`,population:`около 46 тыс.`,hub:`Липецке`,intro:`Грязи — крупный железнодорожный узел Липецкой области. Через город проходит много людей, поэтому придорожные кафе, столовые и точки на вокзале — основные работодатели для персонала общепита.`,scene:`Спрос создают кафе у вокзала, придорожные комплексы на трассе и столовые. Здесь ценятся скорость, аккуратность и готовность работать в смену.`,districts:[`Вокзал`,`Центр`,`Трасса М-4`,`Микрорайоны`],demand:`Повара-универсалы, кухонные работники, кассиры и официанты. На трассе часто нужны люди на ночные смены.`,season:`Круглый год, с ростом в летний сезон отпусков и в праздники.`,rates:`Ставка — 2 000–3 500 ₽. Ночные смены на трассе оплачиваются выше.`,faqs:[{q:`Где искать работу в Грязях?`,a:`В придорожных кафе, столовых и на вокзале. Также стоит смотреть Липецк: он в 30–40 минутах, и заведений там гораздо больше.`},{q:`Есть ли ночные смены?`,a:`Да, трассовые кафе работают круглосуточно и регулярно ищут персонал на ночь с доплатой.`},{q:`Нужен ли опыт?`,a:`Нет, на кухонные позиции и кассу берут с обучением. Опыт нужен для повара горячего цеха.`}]},{slug:`dankov`,name:`Данков`,nameIn:`Данкове`,nameOf:`Данкова`,region:`Липецкая область`,population:`около 20 тыс.`,hub:`Липецке`,intro:`Данков — тихий город Липецкой области с кафе в центре и придорожным общепитом. Работа здесь появляется нечасто, зато требования ниже, а попасть на первую смену проще, чем в крупных городах.`,scene:`Основные точки — кафе в центре, столовые и заведения на трассе. Туристический поток небольшой, поэтому спрос зависит от местных гостей и сезонных событий.`,districts:[`Центр`,`Трасса`,`Заречье`],demand:`Повар-универсал, помощник повара, официант и кассир. Чаще всего нужны люди на подмену и сезон отпусков.`,season:`Спрос ровный, с небольшим ростом летом и в новогодние праздники.`,rates:`Ставка — 1 800–3 200 ₽. В Липецке ставки выше на 20–40%.`,faqs:[{q:`Можно ли найти работу в Данкове через сервис?`,a:`Да, но заявок немного. Заполните анкету и отметьте готовность к сменам в Липецке — там выбор шире.`},{q:`Какие позиции чаще всего свободны?`,a:`Помощник повара, кухонный работник и кассир. Для повара горячего цеха вакансии появляются реже.`},{q:`Как быстро выплачивают?`,a:`Обычно в день смены. В небольших заведениях иногда на следующий день — уточняйте до выхода.`}]},{slug:`elets`,name:`Елец`,nameIn:`Ельце`,nameOf:`Ельца`,region:`Липецкая область`,population:`около 100 тыс.`,hub:`Липецке`,intro:`Елец — один из старейших городов Липецкой области с туристическим центром и развитой сетью кафе и кофеен. Здесь есть и локальные проекты, и федеральные сети, поэтому смены находятся и в будни, и в выходные.`,scene:`Центр и пешеходные улицы — кафе и кофейни, сети работают в торговых центрах, а придорожный общепит — на трассе. В выходные добавляется туристический поток.`,districts:[`Центр`,`Улица Мира`,`ТЦ`,`Трасса`],demand:`Официанты, бариста, повара и кондитеры. Сети дают стабильный график, локальные проекты — гибкие смены.`,season:`Май–сентябрь и новогодние праздники. Осенью и весной спрос держится за счёт сетей и деловых обедов.`,rates:`Ставка — 2 300–3 800 ₽. В центре и на банкетах выше.`,faqs:[{q:`Есть ли в Ельце работа бариста?`,a:`Да, кофейни в центре и в торговых центрах регулярно ищут сотрудников и часто берут стажёров.`},{q:`Можно ли совмещать с учёбой?`,a:`Да, смены в кофейнях и сетях можно брать на вечер и выходные, без обязательного количества часов.`},{q:`Стоит ли смотреть Липецк?`,a:`Если нужна более высокая ставка — да: до Липецка около часа, и там больше заведений и банкетных площадок.`}]},{slug:`efremov`,name:`Ефремов`,nameIn:`Ефремове`,nameOf:`Ефремова`,region:`Тульская область`,population:`около 35 тыс.`,hub:`Туле и Ельце`,intro:`Ефремов стоит на трассе М-4, поэтому значительная часть общепита ориентирована на проезжающих. Это создаёт стабильный спрос на поваров и кассиров, в том числе на ночные смены.`,scene:`Придорожные комплексы, кафе в центре и столовые на предприятиях. Формат быстрый: важны скорость, чистота и работа в смене.`,districts:[`Центр`,`Трасса М-4`,`Микрорайоны`],demand:`Повара-универсалы, кухонные работники, кассиры и официанты. Ночные смены на трассе востребованы постоянно.`,season:`Круглый год, с ростом в сезон отпусков и в новогодние праздники.`,rates:`Ставка — 2 000–3 500 ₽. Ночью и на трассе — выше.`,faqs:[{q:`Много ли работы на трассе?`,a:`Да, Ефремов — узел на М-4, и придорожные кафе работают круглосуточно. Там регулярно нужны повара и кассиры.`},{q:`Есть ли смены в центре?`,a:`Да, но их меньше: кафе и столовые. Основной объём даёт трасса.`},{q:`Нужна ли медкнижка?`,a:`Для постоянной работы — почти всегда да. На короткую подмену некоторые заведения берут без неё.`}]},{slug:`korolev`,name:`Королёв`,nameIn:`Королёве`,nameOf:`Королёва`,region:`Московская область`,population:`около 230 тыс.`,hub:`Москве`,intro:`Королёв — наукоград и один из крупнейших городов Подмосковья. Здесь много жилых комплексов, торговых центров и кофеен у дома, а до Москвы можно добраться на электричке за 25–40 минут.`,scene:`Спрос сосредоточен в ТЦ, кофейнях в новых ЖК и ресторанах в центре. Многие жители работают в Москве, поэтому вечерние смены и выходные — самое востребованное время.`,districts:[`Центр`,`Костино`,`Юбилейный`,`ТЦ`,`Новые ЖК`],demand:`Бариста, официанты, повара и пиццайоло. Сети в ТЦ набирают круглый год, кофейни у дома — на утро и выходные.`,season:`Спрос ровный, пик — сентябрь–декабрь и март–май. Летом добавляются веранды.`,rates:`Ставка — 3 000–5 000 ₽: выше, чем в большинстве областных центров, но ниже московской.`,faqs:[{q:`Работать в Королёве или ехать в Москву?`,a:`В Королёве меньше дорога и ниже конкуренция, в Москве выше ставки. Многие берут смены рядом с домом, а на высокие ставки выезжают в столицу.`},{q:`Есть ли работа в новых ЖК?`,a:`Да, кофейни и пиццерии в новых кварталах постоянно ищут сотрудников и часто готовы обучать.`},{q:`Какой график выбрать при работе в Москве?`,a:`Если совмещаете, берите вечерние смены и выходные: в Королёве такие заявки появляются регулярно.`}]},{slug:`lebedjan`,name:`Лебедянь`,nameIn:`Лебедяни`,nameOf:`Лебедяни`,region:`Липецкая область`,population:`около 19 тыс.`,hub:`Липецке`,intro:`Лебедянь — небольшой город Липецкой области, известный пищевой промышленностью. Общепит здесь представлен кафе в центре, столовыми и придорожными точками, а спрос на персонал невысокий, но стабильный.`,scene:`Кафе в центре, столовые на предприятиях и придорожные заведения. Работа чаще всего сменная, с подменой на выходные и в сезон отпусков.`,districts:[`Центр`,`Трасса`,`Рабочие кварталы`],demand:`Повар-универсал, помощник повара, кассир и официант. Опыт приветствуется, но не всегда обязателен.`,season:`Круглый год, с небольшим ростом летом.`,rates:`Ставка — 1 800–3 200 ₽. В Липецке — выше.`,faqs:[{q:`Есть ли работа в Лебедяни?`,a:`Да, но заявок немного: кафе, столовая и придорожный общепит. Стоит также смотреть Липецк — около 40 минут на машине.`},{q:`Можно ли работать на пищевом производстве?`,a:`GastroConnect — про общепит, но навыки работы с продуктами и санитарией там пригодятся и помогут быстрее получить смену.`},{q:`Что нужно для старта?`,a:`Заполнить анкету, указать город и опыт. Медицинская книжка расширяет доступные заведения.`}]},{slug:`livny`,name:`Ливны`,nameIn:`Ливнах`,nameOf:`Ливен`,region:`Орловская область`,population:`около 48 тыс.`,hub:`Орле и Воронеже`,intro:`Ливны — город в Орловской области с развитой пищевой промышленностью и сетью кафе. Рынок общепита небольшой, но стабильный: местные жители регулярно посещают кафе и заказывают доставку.`,scene:`Кафе и кофейни в центре, столовые на предприятиях, пиццерии и доставка. В выходные спрос выше за счёт семейных визитов.`,districts:[`Центр`,`Микрорайоны`,`Трасса`],demand:`Повара, официанты, бариста и пиццайоло. Доставка набирает водителей и поваров на вечерние смены.`,season:`Круглый год, пик — новогодние праздники и летние выходные.`,rates:`Ставка — 2 000–3 500 ₽. В Орле и Воронеже выше.`,faqs:[{q:`Где искать смены в Ливнах?`,a:`В кафе центра, пиццериях и доставке. Также можно смотреть Орёл — около часа пути.`},{q:`Есть ли работа без опыта?`,a:`Да, в пиццериях и кафе часто берут на кухню с обучением.`},{q:`Как оплачивается смена?`,a:`Обычно фиксированная ставка, выплата в день смены или на следующий рабочий день.`}]},{slug:`lipetsk`,name:`Липецк`,nameIn:`Липецке`,nameOf:`Липецка`,region:`Липецкая область`,population:`около 500 тыс.`,hub:`Воронеже`,intro:`Липецк — промышленный центр с большим числом сетевых ресторанов, кофеен и кухонь доставки. Порог входа ниже, чем в столицах, а ставки выше, чем в соседних малых городах.`,scene:`Центр и улица Зегеля — рестораны и кофейни, торговые центры — сети, новые ЖК — пиццерии и доставка. Спрос ровный в течение года.`,districts:[`Центр`,`Улица Зегеля`,`ТЦ`,`Новые ЖК`,`Левобережный`],demand:`Повара, официанты, бариста, пиццайоло и бармены. Доставка стабильно набирает поваров на вечерние смены.`,season:`Сентябрь–декабрь и март–май, плюс летние веранды. Зимой растёт доставка.`,rates:`Ставка — 2 500–4 300 ₽. В центре и на банкетах выше.`,faqs:[{q:`Много ли работы в Липецке?`,a:`Да, это один из крупнейших рынков Черноземья: сети, кофейни, доставка и банкетные площадки ищут персонал круглый год.`},{q:`Берут ли без опыта?`,a:`Да, в сетях и доставке. Начните с кухни или кассы, затем можно перейти в зал.`},{q:`Какие смены удобны для совмещения?`,a:`Вечерние смены и выходные: заведения Липецка публикуют их чаще всего.`}]},{slug:`michurinsk`,name:`Мичуринск`,nameIn:`Мичуринске`,nameOf:`Мичуринска`,region:`Тамбовская область`,population:`около 90 тыс.`,hub:`Тамбове`,intro:`Мичуринск — наукоград садоводства с компактным, но живым центром. Кафе и кофейни здесь ориентированы на местных жителей и студентов, поэтому смены появляются регулярно.`,scene:`Центр и пешеходные улицы — кафе и кофейни, сети работают в торговых центрах, а на трассе — придорожный общепит. В выходные добавляются семейные визиты.`,districts:[`Центр`,`ТЦ`,`Трасса`,`Микрорайоны`],demand:`Повара, официанты, бариста и кондитеры. Кондитерские и пекарни ценят аккуратность и опыт с выпечкой.`,season:`Круглый год, с ростом в новогодние праздники и в летний сезон.`,rates:`Ставка — 2 200–3 700 ₽. В Тамбове выше на 10–20%.`,faqs:[{q:`Есть ли работа в Мичуринске?`,a:`Да, кафе, кофейни и сети центра регулярно ищут персонал. Заявок меньше, чем в Тамбове, но и конкуренция ниже.`},{q:`Нужен ли опыт кондитера?`,a:`Для позиции кондитера — да, хотя бы базовый. В пекарни и кофейни часто берут помощников с обучением.`},{q:`Можно ли работать в Тамбове?`,a:`Да, до Тамбова около часа. В анкете можно указать оба города и готовность к выездным сменам.`}]},{slug:`rasskazovo`,name:`Рассказово`,nameIn:`Рассказове`,nameOf:`Рассказово`,region:`Тамбовская область`,population:`около 43 тыс.`,hub:`Тамбове`,intro:`Рассказово — город рядом с Тамбовом, известный вязальным промыслом. Общепит здесь преимущественно местный: кафе, пиццерии и столовые, а часть жителей ежедневно ездит на работу в Тамбов.`,scene:`Кафе в центре, пиццерии и доставка, столовые на предприятиях. В выходные спрос выше — семейные обеды и дни рождения.`,districts:[`Центр`,`Микрорайоны`,`Трасса`],demand:`Повара, официанты, пиццайоло и кассиры. Доставка ищет поваров на вечерние смены.`,season:`Круглый год, с пиком в новогодние праздники.`,rates:`Ставка — 2 000–3 400 ₽. В Тамбове — выше.`,faqs:[{q:`Стоит ли работать в Рассказове или ездить в Тамбов?`,a:`В Рассказове меньше дорога и ниже конкуренция, в Тамбове больше смен и выше ставки. Можно совмещать: брать смены в обоих городах.`},{q:`Какие позиции востребованы?`,a:`Повар-универсал, пиццайоло, официант и кассир. Чаще всего требуются люди на подмену.`},{q:`Как быстро можно начать?`,a:`После заполнения анкеты — в течение нескольких дней, если в городе есть активные заявки.`}]},{slug:`uzlovaya`,name:`Узловая`,nameIn:`Узловой`,nameOf:`Узловой`,region:`Тульская область`,population:`около 50 тыс.`,hub:`Туле и Новомосковске`,intro:`Узловая — город в Тульской области с крупным железнодорожным узлом. Через него проходит много пассажиров, поэтому вокзальные кафе и придорожный общепит — основные работодатели.`,scene:`Кафе у вокзала, столовые на предприятиях и точки на трассе. В будни поток ровный, в выходные и праздники — выше.`,districts:[`Вокзал`,`Центр`,`Трасса`,`Микрорайоны`],demand:`Повар-универсал, кухонный работник, кассир и официант. Ночные смены на вокзале и трассе — регулярно.`,season:`Круглый год, с ростом в сезон отпусков.`,rates:`Ставка — 2 000–3 400 ₽. В Туле и Новомосковске выше.`,faqs:[{q:`Где искать смены в Узловой?`,a:`На вокзале, в столовых и придорожных кафе. Также стоит смотреть Новомосковск — он рядом.`},{q:`Есть ли ночная работа?`,a:`Да, вокзальные и трассовые кафе работают круглосуточно и ищут людей на ночные смены с доплатой.`},{q:`Нужна ли медкнижка?`,a:`Для постоянной работы — да. На разовую смену иногда берут без неё.`}]},{slug:`sochi`,name:`Сочи`,nameIn:`Сочи`,nameOf:`Сочи`,region:`Краснодарский край`,population:`около 460 тыс.`,hub:`Краснодаре`,intro:`Сочи — главный курорт страны, и общепит здесь работает по сезону: с мая по октябрь заведения на набережной и в горах загружены почти круглосуточно, а зимой добавляется горнолыжный поток в Красной Поляне.`,scene:`Набережная, Морпорт и Красная Поляна — три разных рынка. В отеле нужны официанты и повара на шведский стол, на набережной — бармены и раннеры, в горах — универсалы на сезон.`,districts:[`Набережная`,`Морпорт`,`Адлер`,`Красная Поляна`,`Мамайка`],demand:`Повара, официанты, бармены, бариста и хостес. В высокий сезон заведения набирают целые команды, часто с проживанием и питанием.`,season:`Май–октябрь — пляжный сезон, декабрь–март — горнолыжный. Межсезонье (ноябрь, апрель) — самое низкое время для смен.`,rates:`Ставка — 3 000–5 500 ₽. В сезон и в отелях выше, часто добавляются проживание и питание.`,faqs:[{q:`Берут ли на сезон с проживанием?`,a:`Да, отели и крупные рестораны Сочи часто предлагают проживание и питание на время сезона. Условия указаны в заявке.`},{q:`Когда лучше приезжать на заработки?`,a:`С мая по сентябрь и с декабря по март. В межсезонье заведений работает меньше, и смен почти нет.`},{q:`Можно ли работать в Красной Поляне без машины?`,a:`Да, из Адлера и Сочи ходят автобусы и электрички. Многие заведения помогают с трансфером для сотрудников.`}]},{slug:`vladivostok`,name:`Владивосток`,nameIn:`Владивостоке`,nameOf:`Владивостока`,region:`Приморский край`,population:`около 600 тыс.`,hub:`Хабаровске`,intro:`Владивосток — тихоокеанская столица России с сильной ресторанной сценой: морепродукты, паназиатская кухня и кофейни на набережной. Город компактный, а спрос на персонал держится круглый год.`,scene:`Центр и Светланская — рестораны и бары, набережная и Золотой мост — туристические точки, а в новых районах открываются кофейни и пиццерии. Повара с опытом работы с рыбой особенно ценятся.`,districts:[`Светланская`,`Центр`,`Набережная`,`Чуркин`,`Патрокл`],demand:`Повара, сушисты, официанты, бармены и бариста. Рестораны морепродуктов ищут людей с опытом работы с рыбой и морепродуктами.`,season:`Июнь–сентябрь — туристы и набережная, декабрь — корпоративы. Основной спрос ровный за счёт локальных гостей.`,rates:`Ставка — 3 000–5 000 ₽. В центре и ресторанах морепродуктов выше.`,faqs:[{q:`Нужен ли опыт работы с рыбой?`,a:`Для сушиста и повара морепродуктов — да. На линейные позиции и в кофейни берут с обучением.`},{q:`Есть ли работа в зимний сезон?`,a:`Да, город живёт не только туризмом: рестораны центра, кофейни и доставка работают круглый год.`},{q:`Как далеко ездить на смены?`,a:`Владивосток компактный: из большинства районов до центра 20–40 минут. Укажите район в анкете, чтобы получать близкие заявки.`}]},{slug:`kaliningrad`,name:`Калининград`,nameIn:`Калининграде`,nameOf:`Калининграда`,region:`Калининградская область`,population:`около 490 тыс.`,hub:`Светлогорске и Зеленоградске`,intro:`Калининград — западный форпост России с европейской архитектурой и растущим турпотоком. Летом город и курорты области принимают много гостей, поэтому персонал в общепите востребован с мая по сентябрь.`,scene:`Центр и остров Канта — рестораны и кофейни, Рыбная деревня — туристические точки. Летом добавляются Светлогорск и Зеленоградск, куда набирают персонал на сезон.`,districts:[`Центр`,`Остров Канта`,`Рыбная деревня`,`Амалиенау`,`Светлогорск`],demand:`Официанты, повара, бариста и бармены. В сезон курорты области набирают команды с проживанием.`,season:`Май–сентябрь — туристы и курорты, декабрь — новогодние программы. Зимой спрос держат центр и сети.`,rates:`Ставка — 2 800–4 800 ₽. На курортах в сезон выше, часто с проживанием.`,faqs:[{q:`Можно ли работать на море летом?`,a:`Да, Светлогорск и Зеленоградск в сезон активно набирают персонал. Обычно предлагают проживание и питание.`},{q:`Что с работой зимой?`,a:`Зимой основной спрос — в центре Калининграда: рестораны, кофейни, сети и доставка.`},{q:`Нужен ли опыт для сезонной работы?`,a:`Часто нет: курортные заведения обучают на месте под поток гостей.`}]},{slug:`tyumen`,name:`Тюмень`,nameIn:`Тюмени`,nameOf:`Тюмени`,region:`Тюменская область`,population:`около 860 тыс.`,hub:`Екатеринбурге`,intro:`Тюмень — один из самых обеспеченных городов России, и это отражается на общепите: много ресторанов, кофеен и семейных форматов. Спрос на персонал стабильный, ставки выше средних по Уралу.`,scene:`Цветной бульвар и центр — рестораны и кофейни, ТРЦ — сети, новые ЖК — заведения у дома. Город компактный, добираться до смен удобно.`,districts:[`Цветной бульвар`,`Центр`,`ТРЦ`,`Новые ЖК`,`Заречный`],demand:`Повара, официанты, бариста, кондитеры и бармены. Семейные рестораны ищут людей с опытом работы с детскими меню и большими столами.`,season:`Сентябрь–декабрь и март–май. Летом добавляются веранды, зимой — банкеты.`,rates:`Ставка — 2 800–4 800 ₽. В центре и на банкетах выше.`,faqs:[{q:`Много ли работы в Тюмени?`,a:`Да, город активно застраивается, и новые заведения открываются регулярно. Смены есть и в сетях, и в локальных проектах.`},{q:`Берут ли без опыта?`,a:`Да, в кофейнях, сетях и доставке. Начать можно с кухни или кассы.`},{q:`Какие ставки в Тюмени?`,a:`Выше, чем в большинстве городов Урала, но ниже московских. Точная ставка всегда указана в заявке.`}]},{slug:`saratov`,name:`Саратов`,nameIn:`Саратове`,nameOf:`Саратова`,region:`Саратовская область`,population:`около 890 тыс.`,hub:`Волгограде`,intro:`Саратов — крупный город на Волге с университетами и развитой сетью кафе. Спрос на персонал ровный: сети и доставка набирают круглый год, а летом добавляются веранды и набережная.`,scene:`Проспект Столыпина и центр — рестораны и кофейни, набережная Космонавтов — сезонные площадки, новые ЖК — пиццерии и доставка.`,districts:[`Проспект Столыпина`,`Центр`,`Набережная Космонавтов`,`Новые ЖК`,`Заводской`],demand:`Повара, официанты, бариста и пиццайоло. Доставка ищет поваров на вечерние смены.`,season:`Май–сентябрь и декабрь. В остальное время спрос держат сети, доставка и университетские кафе.`,rates:`Ставка — 2 500–4 200 ₽. В центре выше, в сетях — средняя по городу.`,faqs:[{q:`Можно ли совмещать с учёбой в Саратове?`,a:`Да, в городе много вузов, и кафе рядом с ними берут студентов на вечерние смены и выходные.`},{q:`Есть ли работа без опыта?`,a:`Да, в сетях, пиццериях и доставке обучают с нуля.`},{q:`Когда сезон веранд?`,a:`С мая по сентябрь. В это время на набережной и в центре появляются дополнительные смены.`}]},{slug:`irkutsk`,name:`Иркутск`,nameIn:`Иркутске`,nameOf:`Иркутска`,region:`Иркутская область`,population:`около 615 тыс.`,hub:`Улан-Удэ`,intro:`Иркутск — ворота Байкала: летом и зимой город принимает туристов, а вместе с ними растёт спрос на персонал в кафе и ресторанах. Центр компактный, и большинство заведений находится в шаговой доступности.`,scene:`Улица Карла Маркса и центр — рестораны и кофейни, набережная Ангары — прогулочные точки, а летом добавляются маршруты на Байкал с сезонными кафе.`,districts:[`Улица Карла Маркса`,`Центр`,`Набережная Ангары`,`Свердловский`,`Академгородок`],demand:`Повара, официанты, бариста и бармены. В сезон Байкала нужны люди на смены в туристических точках и на базах отдыха.`,season:`Июнь–сентябрь и январь–март: летний и зимний туристический пик. Межсезонье — спокойнее.`,rates:`Ставка — 2 800–4 500 ₽. На туристических направлениях и базах выше, иногда с питанием.`,faqs:[{q:`Есть ли работа на Байкале?`,a:`Да, в сезон базы отдыха и кафе на побережье ищут поваров и официантов, обычно с проживанием.`},{q:`Что делать в межсезонье?`,a:`Работать в центре Иркутска: сети, кофейни и доставка набирают персонал круглый год.`},{q:`Берут ли без опыта?`,a:`Да, в кофейнях и сетях. Для повара на туристическую точку чаще нужен опыт.`}]},{slug:`khabarovsk`,name:`Хабаровск`,nameIn:`Хабаровске`,nameOf:`Хабаровска`,region:`Хабаровский край`,population:`около 615 тыс.`,hub:`Владивостоке`,intro:`Хабаровск — крупный центр Дальнего Востока с набережной Амура и сильной ресторанной сценой. Здесь много деловых обедов и семейных ресторанов, поэтому спрос на персонал стабилен в течение года.`,scene:`Улица Муравьёва-Амурского и центр — рестораны и кофейни, набережная Амура — сезонные площадки, сети работают в ТРЦ.`,districts:[`Муравьёва-Амурского`,`Центр`,`Набережная Амура`,`ТРЦ`,`Северный`],demand:`Повара, официанты, бариста и бармены. Деловые рестораны ищут людей с опытом быстрого сервиса в обед.`,season:`Май–сентябрь — набережная и туристы, декабрь — корпоративы. Зимой спрос держат центр и сети.`,rates:`Ставка — 2 800–4 800 ₽. В центре и на банкетах выше.`,faqs:[{q:`Много ли смен в Хабаровске?`,a:`Да, город крупный, и заведения центра регулярно ищут персонал. Конкуренция ниже, чем в Москве.`},{q:`Есть ли сезонная работа?`,a:`Летом на набережной открываются площадки, а зимой — новогодние программы и корпоративы.`},{q:`Как быстро можно начать?`,a:`После заполнения анкеты — в течение нескольких дней, если в городе есть активные заявки.`}]},{slug:`tomsk`,name:`Томск`,nameIn:`Томске`,nameOf:`Томска`,region:`Томская область`,population:`около 570 тыс.`,hub:`Новосибирске`,intro:`Томск — студенческий город с сильной кофейной культурой и большим числом вузов. Кафе рядом с университетами регулярно ищут сотрудников на гибкий график, а центр радует исторической архитектурой и потоком гостей.`,scene:`Проспект Ленина и центр — кофейни, рестораны и бары, студенческие кампусы — кафе с утренними сменами, новые ЖК — пиццерии и доставка.`,districts:[`Проспект Ленина`,`Центр`,`Кампусы вузов`,`Новые ЖК`,`Академгородок`],demand:`Бариста, официанты, повара и кондитеры. Кофейни ищут студентов на утренние и вечерние смены.`,season:`Сентябрь–декабрь и февраль–май — учебный год, летом спрос ниже, но кофейни продолжают работать.`,rates:`Ставка — 2 500–4 300 ₽. В центре и на банкетах выше.`,faqs:[{q:`Удобно ли работать студенту в Томске?`,a:`Да, кафе рядом с вузами подстраиваются под расписание: можно брать утренние, вечерние смены или только выходные.`},{q:`Много ли кофеен?`,a:`Да, Томск известен кофейной культурой. Это самый доступный вход в профессию бариста.`},{q:`Что с работой летом?`,a:`Летом студентов меньше, и смен становится меньше, но сети и доставка работают стабильно.`}]}];function i(n,r){let i=`Работа в HoReCa в ${n.nameIn}`;return{slug:`goroda/${n.slug}`,title:`Работа и смены в HoReCa в ${n.nameIn}`,description:`Работа и подработка в ресторанах, кафе и кофейнях ${n.nameOf}: повар, официант, бариста, бармен. Ставка до смены, выплаты день в день, ${n.region}.`,eyebrow:`HoReCa · ${n.name}`,h1:i,lead:`${n.intro} Одна анкета — и заведения ${n.nameOf} сами приглашают вас на смены.`,image:n.slug===`moskva`||n.slug===`sankt-peterburg`?t:e,imageAlt:`Команда ресторана в ${n.nameIn}`,chips:[n.region,`Смены и подработка`,`${n.population} жителей`],serviceType:`Подбор работы и смен в HoReCa в ${n.nameIn}`,city:n.name,cta:{to:`/auth`,label:`Создать анкету`,search:{mode:`signup`,role:`worker`}},sections:[{title:`Кому нужны сотрудники в ${n.nameIn}`,text:n.scene,bullets:n.districts},{title:`Какие позиции востребованы`,text:n.demand,bullets:[`Повар горячего и холодного цеха`,`Официант, раннер, бармен`,`Бариста и кондитер`,`Су-шеф и заготовщик`]},{title:`Сезонность и загрузка`,text:n.season,bullets:[`Разовые смены и замены`,`Постоянный график`,`Банкеты и события`,`Работа рядом с домом`]},{title:`Ставки и выплаты`,text:n.rates,bullets:[`Ставка известна до выхода`,`Без комиссии для соискателя`,`Выплата день в день или на следующий рабочий день`,`Условия указаны в заявке`]}],...r?{cities:[{name:`Ближайший крупный рынок`,text:`${r}. Там больше заведений и выше ставки, а доехать можно на машине или электричке.`}]}:{},faq:n.faqs,related:[{to:`/podrabotka-povarom`,label:`Подработка поваром`},{to:`/podrabotka-ofitsiantom`,label:`Подработка официантом`},{to:`/podrabotka-barista`,label:`Подработка бариста`},{to:`/goroda`,label:`Все города России`},{to:`/personal-horeca`,label:`Персонал для заведений`}]}}var a=Object.fromEntries([...n.map(e=>[e.slug,i(e)]),...r.map(e=>[e.slug,i(e,e.hub)])]);[...n,...r].map(e=>e.slug);var o=[...n,...r].map(e=>({name:e.name,slug:e.slug,to:`/goroda/${e.slug}`,text:`${e.region} · ${e.population}. Смены для персонала, заявки заведений и поставщики.`}));export{a as n,o as t};